// SearchFinanceEntries is the filtered, paged ledger of one organization.
// reversed_by_uuid is set when the row has been reversed (void).
// TEC-379 (DT-BE-8): list contract (docs/list-contract.md): direction,
// category and source_type are lists, amount_min / amount_max bound the
// signed amount in the book currency, q matches the description, the
// account name or the cari counterparty name; id is the tiebreak (an empty
// sort_key orders by id only, as the single-entry lookup does).
func (q *Queries) SearchFinanceEntries(ctx context.Context, arg SearchFinanceEntriesParams) ([]SearchFinanceEntriesRow, error) {
	rows, err := q.db.Query(ctx, searchFinanceEntries,
		arg.OrganizationID,
		arg.AccountID,
		arg.CariID,
		arg.Directions,
		arg.Categories,
		arg.SourceTypes,
		arg.CreatedFrom,
		arg.CreatedTo,
		arg.AmountMin,
		arg.AmountMax,
		arg.Q,
		arg.EntryUuid,
		arg.SortDesc,
		arg.SortKey,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchFinanceEntriesRow{}
	for rows.Next() {
		var i SearchFinanceEntriesRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.BrandID,
			&i.AccountID,
			&i.CariID,
			&i.Direction,
			&i.Category,
			&i.OrigCurrency,
			&i.OrigAmount,
			&i.Currency,
			&i.Amount,
			&i.Rate,
			&i.RateDate,
			&i.SourceType,
			&i.SourceUuid,
			&i.Role,
			&i.Revision,
			&i.ReversalOfID,
			&i.Description,
			&i.ActorUserID,
			&i.CreatedAt,
			&i.AccountUuid,
			&i.AccountName,
			&i.CariUuid,
			&i.CounterpartyOrgUuid,
			&i.CounterpartyOrgName,
			&i.ReversedByUuid,
			&i.ReversalOfUuid,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
